{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Berkeley Rent Stabilization Ordinance coverage","requirement":"Rent increases are controlled for most multifamily units built before 1980 and for single-family homes whose tenancy began before 1996; units with a Certificate of Occupancy after June 1980 and most condominiums are not rent-controlled.","key_value":"Covered: built before 1980; not covered: Certificate of Occupancy after June 1980","coverage_conditions":"Most multifamily properties built before 1980; single-family homes with tenancies begun before 1996; rooming houses with five or more rooms rented individually. Newer construction and condominiums are only partially covered, with no rent control.","applicability":{"built_on_or_before":"1980-06","built_after":null,"date_basis":"certificate_of_occupancy","min_units":null,"max_units":null,"owner_dependent":true,"other":"Single-family homes with tenancy begun before 1996 are rent-controlled; those with tenancy on or after 1996 are not"},"exemptions":"Owner-occupied Golden Duplex; unit where owner shares kitchen or bath and lived on the property when the tenancy began; tenancies started after Nov 7, 2018 where one unit is an owner-occupied ADU; university dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"citation":"Berkeley Rent Stabilization and Eviction for Just Cause Ordinance","quoted_span":"Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley just cause for eviction coverage","requirement":"A landlord may end a tenancy only for just cause in every unit that is fully or partially covered by the ordinance, including post-June 1980 construction, condominiums and certain subsidized units; exempt units are not covered.","key_value":null,"coverage_conditions":"All fully covered and partially covered unit types, including units built after June 1980, most condominiums, single-family homes with tenancies begun on or after January 1, 1996, and listed subsidized units. Exempt unit types are excluded.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"unspecified","min_units":null,"max_units":null,"owner_dependent":true,"other":"Coverage is by unit and tenancy type per the coverage table; no building-age cutoff for just cause"},"exemptions":"Owner-occupied Golden Duplex; unit where owner shares kitchen or bath and lived on the property when the tenancy began; tenancies started after Nov 7, 2018 where one unit is an owner-occupied ADU; university dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"citation":"Berkeley Rent Stabilization and Eviction for Just Cause Ordinance","quoted_span":"Most condominiums** Partially Covered Yes No Yes Yes","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"security_deposits","lifecycle":"enacted","title":"Berkeley security deposit interest coverage","requirement":"Landlords of units fully or partially covered by the ordinance must pay interest on tenants' security deposits as the ordinance requires; owners of exempt units need not.","key_value":null,"coverage_conditions":"All unit types shown as fully covered or partially covered, including single-family homes with pre-1996 tenancies, post-June 1980 construction, most condominiums and listed subsidized units. Exempt unit types are excluded.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"unspecified","min_units":null,"max_units":null,"owner_dependent":true,"other":"Deposit interest follows the coverage table; no building-age cutoff stated"},"exemptions":"Owner-occupied Golden Duplex; unit where owner shares kitchen or bath and lived on the property when the tenancy began; tenancies started after Nov 7, 2018 where one unit is an owner-occupied ADU; university dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"citation":"Berkeley Rent Stabilization and Eviction for Just Cause Ordinance","quoted_span":"Single family homes with current tenancies that began before 1996** Fully Covered Yes Yes Yes Yes","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
